mapper.select:
select t.create_staff_name,t.create_staff_name createStaffName,t.query_way,t.query_way
queryWay,t.create_staff_id,t.create_staff_id createStaffId,t.status_cd,t.status_cd
statusCd,t.remark,t.state,t.mq_id,t.mq_id mqId,t.qrcode_name,t.qrcode_name
qrcodeName,t.community_id,t.community_id communityId,t.create_time createTime,td.name queryWayName
from meter_qrcode t
left join t_dict td on t.query_way = td.status_cd and td.table_name = 'meter_qrcode' and td.table_columns = 'query_way'
where 1 =1

    and t.create_staff_name= #{createStaffName}


    and t.query_way= #{queryWay}


    and t.create_staff_id= #{createStaffId}


    and t.status_cd= #{statusCd}


    and t.remark= #{remark}


    and t.state= #{state}


    and t.mq_id= #{mqId}


    and t.qrcode_name= #{qrcodeName}


    and t.community_id= #{communityId}


    and t.qrcode_name like concat('%', #{qrcodeNameLike}, '%')

order by t.create_time desc

    limit #{page}, #{row}

